export function legalView(path) {
  const page = content[path] || content['/support'];
  setTitle(page.title);
  return {
    meta: { section: 'public' },
    html: `<main id="main" class="legal page-shell" tabindex="-1">
      <a href="/events" class="back-link" data-link>← Back to events</a>
      <header><p class="kicker">${page.kicker}</p><h1>${page.title}</h1><p>${page.intro}</p></header>
      <div class="legal__sections">${page.sections.map(([title, body], index) => `<section><span>${String(index + 1).padStart(2, '0')}</span><div><h2>${title}</h2><p>${body}</p></div></section>`).join('')}</div>
    </main>`,
  };
}
